import { useEffect, useState } from "react";
import { io } from "socket.io-client";

const socket = io("http://localhost:5000");

function PatientDashboard() {

  const [myOP, setMyOP] = useState(null);

  const [form, setForm] = useState({
    patientName:"",
    doctor:"",
    department:"",
    date:""
  });

  const [queueCount,setQueueCount]=useState(0);

  // GET MY OP
  const fetchData = async()=>{

    const res = await fetch(
      "http://localhost:5000/api/queue/all"
    );

    const data = await res.json();

    // ONLY MY OP
    const mine = data.find(
      q =>
      q.patientName === form.patientName
    );

    if(mine){

      setMyOP(mine);

    }

    // QUEUE COUNT
    const total =
      data.filter(
        q=>q.status==="InQueue"
      ).length;

    setQueueCount(total);

  };

  useEffect(()=>{

    fetchData();

    socket.on(
      "queueUpdated",
      fetchData
    );

    return()=>{
      socket.off();
    };

  },[form.patientName]);


  // BOOK OP
  const bookOP = async()=>{

    const res = await fetch(
      "http://localhost:5000/api/queue/book",
      {
        method:"POST",

        headers:{
          "Content-Type":
          "application/json"
        },

        body:JSON.stringify(form)
      }
    );

    const data =
      await res.json();

    setMyOP(data);

  };


  // JOIN QUEUE
  const joinQueue = async(id)=>{

    await fetch(
      `http://localhost:5000/api/queue/join/${id}`,
      {
        method:"PUT"
      }
    );

  };


  return(

    <div style={{padding:20}}>

      <h2>
      👤 Patient Dashboard
      </h2>

      {!myOP && (

      <>

      <input
      placeholder="Name"

      onChange={(e)=>

      setForm({
        ...form,
        patientName:
        e.target.value
      })

      }
      />

      <input
      placeholder="Doctor"

      onChange={(e)=>

      setForm({
        ...form,
        doctor:
        e.target.value
      })

      }
      />

      <input
      placeholder="Department"

      onChange={(e)=>

      setForm({
        ...form,
        department:
        e.target.value
      })

      }
      />

      <input
      type="date"

      onChange={(e)=>

      setForm({
        ...form,
        date:
        e.target.value
      })

      }
      />

      <button
      onClick={bookOP}
      >

      Book OP

      </button>

      </>

      )}

      <hr/>

      {myOP && (

      <div>

      <h3>
      My OP
      </h3>

      <p>
      Token:
      {myOP.tokenNumber}
      </p>

      <p>
      Status:
      {myOP.status}
      </p>

      {myOP.status==="Confirmed" && (

      <button
      onClick={()=>
      joinQueue(myOP._id)
      }>

      Join Queue

      </button>

      )}

      {myOP.status==="InQueue" && (

      <div>

      <h4>

      Queue Count:
      {queueCount}

      </h4>

      </div>

      )}

      </div>

      )}

    </div>

  );

}

export default PatientDashboard;
